const APP = path.join(KIT, "generated/build/client-optimized/app.js");
const dict = (fs.readFileSync(APP, "utf8").match(/export const dictionary = (\{[\s\S]*?\});/)?.[1] ?? "{}").replace(/,\s*\}/g, "}");
const routes = JSON.parse(dict);
const key = (s) => Object.keys(manifest).find((k) => k.endsWith(s));
const size = (f) => gzipSync(fs.readFileSync(path.join(CLIENT, f)), { level: 9 }).length;
const closure = (starts) => { const seen = new Set(); const walk = (k) => { if (seen.has(k) || !manifest[k]) return; seen.add(k); for (const i of manifest[k].imports ?? []) walk(i); }; starts.forEach(walk); return seen; };
