  const ks = [...closure([...base, ...nodes])];
  let total = 0;
  for (const k of ks.sort((a, b) => size(manifest[b].file) - size(manifest[a].file))) {
    const f = manifest[k].file; const sz = size(f); total += sz;
    const src = fs.readFileSync(path.join(CLIENT, f), "utf8");
